_CODES = ("ko", "en", "ja", "zh-Hans", "zh-Hant", "es", "fr", "de", "pt-BR")
CATALOGS = {code: {} for code in _CODES}
for _row in _ROWS.strip().splitlines():
    _values = [value.replace(r"\n", "\n") for value in _row.split("|")]
    if len(_values) != len(_CODES):
        raise ValueError(f"Invalid translation column count: {_values[0]}")
    for _code, _value in zip(_CODES, _values):
        if _values[0] in CATALOGS[_code]:
            raise ValueError(f"Duplicate translation key: {_values[0]}")
        CATALOGS[_code][_values[0]] = _value

# These are message IDs rather than Korean display strings.
